  max-width: 1200px;
  margin: 0 auto;
  padding: 100px 60px 80px;
  display: grid;
  grid-template-columns: 1fr 1.4fr;
  gap: 60px;
  align-items: center;
}

.ww-tag {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  background: rgba(180,40,0,0.15);
  border: 1px solid rgba(180,40,0,0.25);
  border-radius: 100px;
  padding: 6px 14px;
  margin-bottom: 28px;
}
.ww-tag-dot {
  width: 7px; height: 7px;
  border-radius: 50%;
  background: #cc3300;
  animation: ww-pulse 2s infinite;
  display: inline-block;
  flex-shrink: 0;
}
@keyframes ww-pulse {
  0%, 100% { opacity: 1; transform: scale(1); }
  50% { opacity: 0.5; transform: scale(0.8); }
}
.ww-tag-text {
  font-size: 12px;
  font-weight: 600;
  letter-spacing: 1.5px;
  text-transform: uppercase;
  color: #cc3300;
}
.ww-h1 {
  font-family: 'Space Grotesk', sans-serif;
  font-size: clamp(36px, 4.5vw, 58px);
  font-weight: 700;
  line-height: 1.08;
  letter-spacing: -1.5px;
  color: #ffffff;
  margin-bottom: 20px;
}
.ww-h1-accent { color: #ff8800; }
.ww-sub {
  font-size: 16px;
