  max-width: 1100px;
  margin: 0 auto;
  padding: 100px 60px;
  display: grid;
  grid-template-columns: 340px 1fr;
  gap: 80px;
  align-items: start;
}

.ww-founder-img {
  width: 100%;
  border-radius: 16px;
  display: block;
  object-fit: cover;
  object-position: top;
}

.ww-founder-label {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  margin-bottom: 16px;
}
.ww-founder-label span:first-child {
  width: 20px;
  height: 2px;
  background: #ff8800;
  display: inline-block;
  border-radius: 2px;
}
.ww-founder-label span:last-child {
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 2px;
  text-transform: uppercase;
  color: #ff8800;
}

.ww-founder-headline {
  font-family: 'Space Grotesk', sans-serif !important;
  font-size: clamp(36px, 4vw, 54px);
  font-weight: 700 !important;
  letter-spacing: -1.5px;
  line-height: 1.08;
  color: #0a0a0a;
  margin-bottom: 28px;
}
.ww-founder-headline span { color: #ff8800; }

.ww-founder-text p {
  font-family: 'Space Grotesk', sans-serif !important;
  font-size: 16px;
  color: #333;
  line-height: 1.75;
  font-weight: 400;
  margin-bottom: 16px;
}
.ww-founder-text p:last-child { margin-bottom: 0; }

.ww-founder-divider {
  width: 100%;
  height: 1px;
  background: #e8e8e4;
  margin: 32px 0;
}

.ww-founder-contact {
  font-size: 14px;
  color: #999;
  font-weight: 400;
  line-height: 1.6;
}
.ww-founder-contact a {
  color: #ff8800;
  text-decoration: none;
  font-weight: 600;
}
.ww-founder-contact a:hover { text-decoration: underline; }

@media (max-width: 900px) {
  .ww-founder-inner {
    grid-template-columns: 260px 1fr;
    gap: 48px;
    padding: 80px 40px;
  }
}
@media (max-width: 640px) {
  .ww-founder-inner {
    grid-template-columns: 1fr;
    gap: 32px;
    padding: 60px 24px;
  }
  .ww-founder-img {
    width: 100%;
    max-width: 100%;
    border-radius: 12px;
  }
  .ww-founder-headline { font-size: 35px !important; letter-spacing: -1px; }
  .ww-founder-text p { font-size: 15px; }
}
</style>

