<script>
function wwFaq(btn) {
  var answer = btn.nextElementSibling;
  var icon = btn.querySelector('.ww-faq-icon');
  var isOpen = answer.style.display === 'block';
  document.querySelectorAll('.ww-faq-a').forEach(function(a) { a.style.display = 'none'; });
  document.querySelectorAll('.ww-faq-icon').forEach(function(i) { i.textContent = '+'; });
  if (!isOpen) {
    answer.style.display = 'block';
    icon.textContent = '×';
  }
}
</script>
